 [UnityTest]public IEnumerator R10FarWorld(){var report=new FarReportR10();Directory.CreateDirectory(Evidence);var path=Path.Combine(Evidence,"far-world.json");Assert.That(File.Exists(path),Is.False);Action save=()=>File.WriteAllText(path,JsonUtility.ToJson(report,true));save();
 foreach(var spec in new[]{new RoofSpec{name="same-standard",angle=12,power=100},new RoofSpec{name="same-roof",angle=65,power=100,level=2},new RoofSpec{name="far-fast-35",angle=35,power=100,level=3},new RoofSpec{name="far-high-65",angle=65,power=100,level=3}}){yield return NewRetrySubject(false,true,true,true,true);float rate=spec.level==3?6:2;Call(current,"Configure",JsonUtility.ToJson(new InputSpec{angle=spec.angle,power=spec.power,direction=spec.direction,upgradeLevel=spec.level}));var aim=JsonUtility.ToJson(new Aim{angle=spec.angle,power=spec.power,direction=spec.direction});var work=JsonUtility.ToJson(new Work{direction=spec.direction,distance=rate/60,seconds=1f/60});Call(current,"BeginAim","");Call(current,"PreviewLaunch",aim);Call(current,"BeginSpinCharge","");for(int i=0;i<601;i++){Call(current,"AddSpinWork",work);Call(current,"Tick",1f/60);}Call(current,"ReleaseLaunch",aim);var row=new FarRowR10{id=spec.name,workRate=rate,launch=JsonUtility.ToJson(Field(State(current),"launchReceipt"))};report.rows.Add(row);save();int reached=0;
 for(int i=0;i<6500&&!(bool)Property(current,"Finished");i++){Call(current,"Tick",1f/60);var state=State(current);float x=F(state,"distance");row.maxX=Mathf.Max(row.maxX,x);float[] marks={150,620,750,940,1216};if(reached<marks.Length&&x>marks[reached]){string name="x"+marks[reached];CaptureRoute(spec.name,name);row.frames.Add(name);reached++;}}
 var final=State(current);var sim=Property(current,"ReviewSimulation");row.final=JsonUtility.ToJson(final);row.contactTrace=(string)Call(sim,"ReviewContactTraceJson");row.breaks=new List<BreakRecord>();foreach(var e in (System.Collections.IEnumerable)Field(sim,"BreakEvents"))row.breaks.Add(new BreakRecord{id=(string)Field(e,"id"),material=(string)Field(e,"material"),secondary=(bool)Field(e,"secondary"),time=F(e,"time"),position=(Vector3)Field(e,"position")});save();CaptureRoute(spec.name,"result");if(spec.name=="same-standard"){CaptureFarStaticR10(750,7,"port-loader");CaptureFarStaticR10(940,3,"glass-display");}Assert.That((bool)Property(current,"Finished"),Is.True);Assert.That((string)Field(final,"physicsFault"),Is.Empty,spec.name);
 Call(current,"SetPaused","1");float age=F(State(current),"worldLifeAge");Call(current,"Tick",1f/60);row.pauseStable=F(State(current),"worldLifeAge")==age;Call(current,"SetPaused","0");Call(current,"Prepare","");var reset=State(current);row.resetClean=F(reset,"worldLifeAge")==0&&Convert.ToInt32(Field(reset,"worldStartled"))==0;save();Assert.That(row.pauseStable&&row.resetClean,Is.True);
 Call(current,"ShutdownReviewPhysics");current=null;yield return null;yield return null;}
 report.state="COMPLETED";save();}
 void CaptureFarStaticR10(float x,float y,string name){var c=(Camera)Property(current,"ReviewCamera");var sim=Property(current,"ReviewSimulation");using(var scope=new RenderIsolation(current.gameObject.scene,(UnityEngine.SceneManagement.Scene)Property(sim,"Scene"))){var position=c.transform.position;var rotation=c.transform.rotation;float size=c.orthographicSize,aspect=c.aspect;var output=Path.Combine(Evidence,"remote-render-only");Directory.CreateDirectory(output);foreach(var wh in new[]{new[]{844,390},new[]{390,844}}){c.transform.position=new Vector3(x,y,-32);c.transform.LookAt(new Vector3(x,y,0));c.orthographicSize=wh[0]>wh[1]?9:12;c.aspect=(float)wh[0]/wh[1];var rt=new RenderTexture(wh[0],wh[1],24);rt.Create();var previous=RenderTexture.active;c.targetTexture=rt;RenderTexture.active=rt;c.Render();var image=new Texture2D(wh[0],wh[1],TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,wh[0],wh[1]),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name+"-"+wh[0]+".png"),image.EncodeToPNG());c.targetTexture=null;RenderTexture.active=previous;UnityEngine.Object.DestroyImmediate(image);rt.Release();UnityEngine.Object.DestroyImmediate(rt);}c.transform.SetPositionAndRotation(position,rotation);c.orthographicSize=size;c.aspect=aspect;}}
